package api

import (
	"encoding/json"
	"net/http"

	"example.com/billing/internal/authz"
	"example.com/billing/internal/store"
)

type Invoices struct {
	Store *store.Store
}

func (h Invoices) List(w http.ResponseWriter, r *http.Request) {
	tenant := authz.Tenant(r)
	invs, err := h.Store.InvoicesOf(r.Context(), tenant)
	if err != nil {
		http.Error(w, "store", http.StatusInternalServerError)
		return
	}
	_ = json.NewEncoder(w).Encode(invs)
}

func (h Invoices) Get(w http.ResponseWriter, r *http.Request) {
	inv, err := h.Store.Invoice(r.Context(), r.PathValue("id"))
	if err != nil || !authz.SameTenant(r, inv.TenantID) {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	_ = json.NewEncoder(w).Encode(inv)
}
